-- 階段 12 唯讀驗證（只有 SELECT）。套用前：PRE 應全為 true；套用後：POST 應全為 true。
select 'PRE' phase, '尚未存在 fn_hold_settle_new_ticket' check_name, (to_regprocedure('public.fn_hold_settle_new_ticket(text,boolean,text,jsonb)') is null) ok
union all select 'PRE', '依賴函式存在（current_employee_id、is_staff_desk、fn_tk_today、fn_tk_is_unopened、fn_tk_holding）', (select count(distinct proname) = 5 from pg_proc where pronamespace='public'::regnamespace and proname in ('current_employee_id','is_staff_desk','fn_tk_today','fn_tk_is_unopened','fn_tk_holding'))
union all select 'PRE', '共享票判定函式 fn_tk_shared_has 是已核對的版本（本體 md5 0d0d61af566726ed67f884d3f733856f）', coalesce((select md5(prosrc) = '0d0d61af566726ed67f884d3f733856f' from pg_proc where oid = to_regprocedure('public.fn_tk_shared_has(jsonb,text)')), false)
union all select 'PRE', '階段 06／08／11 的物件都在（trg_tk_quota_guard、fn_desk_deduct_ticket、fn_hold_state_guard）', (exists (select 1 from pg_trigger where tgname='trg_tk_quota_guard' and not tgisinternal) and to_regprocedure('public.fn_desk_deduct_ticket(text,text,text,text)') is not null and to_regprocedure('public.fn_hold_state_guard()') is not null)
union all select 'PRE', '階段 11 函式指紋是測過的版本（adopt 05c51530…／state 22edb0f9…／month e7152b65…）', (coalesce((select md5(prosrc) from pg_proc where oid = to_regprocedure('public.fn_contract_adopt_holds(text,text[],boolean)')), '') = '05c51530e595cf296f9b8da951f66093' and coalesce((select md5(prosrc) from pg_proc where oid = to_regprocedure('public.fn_hold_state_guard()')), '') = '22edb0f9a4893e9d891a420ba4588440' and coalesce((select md5(prosrc) from pg_proc where oid = to_regprocedure('public.fn_hold_month_guard()')), '') = 'e7152b65fbb7d6c5d494cc938757caeb')
union all select 'PRE', 'bookings 有本函式用到的欄位', (select count(*) = 10 from information_schema.columns where table_schema='public' and table_name='bookings' and column_name in ('pending_contract','ticket_id','contract_id','checked_in_at','sibling_of','member_ids','cancel_reason','cancelled_by','cancelled_at','trial_name'))
union all select 'POST', 'security definer＋search_path 固定', coalesce((select prosecdef and coalesce(array_to_string(proconfig, ','), '') = 'search_path=public, pg_temp' from pg_proc where oid = to_regprocedure('public.fn_hold_settle_new_ticket(text,boolean,text,jsonb)')), false)
union all select 'POST', '權限正好 postgres＋authenticated（anon／service_role／public 不能執行）', coalesce((select proacl::text = '{postgres=X/postgres,authenticated=X/postgres}' from pg_proc where oid = to_regprocedure('public.fn_hold_settle_new_ticket(text,boolean,text,jsonb)')), false)
union all select 'POST', '本體指紋＝發布版（md5 550c28a816b6e46f636287d7fa33405a；若函式有改動這裡要一起更新）', coalesce((select md5(prosrc) = '550c28a816b6e46f636287d7fa33405a' from pg_proc where oid = to_regprocedure('public.fn_hold_settle_new_ticket(text,boolean,text,jsonb)')), false)
union all select 'POST', '只有一支同名函式', ((select count(*) from pg_proc where pronamespace='public'::regnamespace and proname='fn_hold_settle_new_ticket') = 1);
